#include <sys/epoll.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

int set_nonblocking(int fd) {
  int fl = fcntl(fd, F_GETFL, 0);
  return fcntl(fd, F_SETFL, fl | O_NONBLOCK);
}

int main() {
  int lfd = socket(AF_INET, SOCK_STREAM, 0);
  int opt = 1;
  setsockopt(lfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
  struct sockaddr_in addr = {AF_INET, htons(8080), {INADDR_ANY}};
  bind(lfd, (struct sockaddr*)&addr, sizeof(addr));
  listen(lfd, 128);
  set_nonblocking(lfd);

  int epfd = epoll_create1(0);
  struct epoll_event ev, events[64];
  ev.events = EPOLLIN;              // LT 模式（默认）
  ev.data.fd = lfd;
  epoll_ctl(epfd, EPOLL_CTL_ADD, lfd, &ev);

  for (;;) {
    int n = epoll_wait(epfd, events, 64, -1);
    for (int i = 0; i < n; ++i) {
      int fd = events[i].data.fd;
      if (fd == lfd) {                       // 新连接
        for (;;) {
          int cfd = accept(lfd, NULL, NULL);
          if (cfd < 0) { if (errno == EAGAIN) break; else break; }
          set_nonblocking(cfd);
          ev.events = EPOLLIN;               // 若用 ET：EPOLLIN | EPOLLET
          ev.data.fd = cfd;
          epoll_ctl(epfd, EPOLL_CTL_ADD, cfd, &ev);
        }
      } else {                               // 已连接 fd 可读
        char buf[4096];
        for (;;) {
          ssize_t r = recv(fd, buf, sizeof(buf), 0);
          if (r > 0) {
            ssize_t off = 0;
            while (off < r) {                // 简化：生产中要处理 send 的 EAGAIN
              ssize_t w = send(fd, buf + off, r - off, 0);
              if (w > 0) off += w;
              else if (errno == EAGAIN) break; // 真实代码需缓冲剩余数据+等 EPOLLOUT
              else break;
            }
          } else if (r == 0) {               // 对端关闭
            epoll_ctl(epfd, EPOLL_CTL_DEL, fd, NULL);
            close(fd);
            break;
          } else if (errno == EAGAIN) {      // LT 下通常一次就够；ET 下靠它收尾
            break;
          } else if (errno == EINTR) {
            continue;
          } else {                           // 真正的错误
            epoll_ctl(epfd, EPOLL_CTL_DEL, fd, NULL);
            close(fd);
            break;
          }
        }
      }
    }
  }
}
